
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_xc_coach_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_coach", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.579808848483500e+00, -3.495082121073816e+00, -3.377249468552396e+00, -3.216028225294804e+00, -3.000650326153978e+00, -2.722189189376918e+00, -2.376729930877703e+00, -1.978965283392256e+00, -1.608187284914328e+00, -1.221718887084082e+00, -6.691575439674441e-01, -4.253739684019201e-01, -3.952328259521617e-01, -3.082575687805179e-01, -2.012658005855768e-01, -9.019940489225114e-02, -1.569605839112078e-02, -2.046812460517895e-03, -6.110108202664209e-05, 2.061496515343737e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


